package com.receiptledger.v1.price;

import com.receiptledger.v1.item.*;import com.receiptledger.v1.persistence.*;import com.receiptledger.v1.product.*;import com.receiptledger.v1.validation.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public class PriceHistoryServiceTest {
 private static ReceiptRecord receipt(String id,String date,long created,String name,long unit,long amount,ValidationStatus status){PersistedItem item=new PersistedItem(0,1,name,1,unit,amount,ValueOrigin.PRINTED,ValueOrigin.PRINTED,ValueOrigin.PRINTED,ItemResolution.EXACT,"exact");return new ReceiptRecord(id,created,date,null,"",amount,amount,0L,amount,0L,status,100,200,false,Collections.emptyList(),Collections.singletonList(item));}
 @Test public void standardTrendExcludesInvalidReceipts(){InMemoryReceiptStore rs=new InMemoryReceiptStore();InMemoryProductCatalogStore ps=new InMemoryProductCatalogStore();rs.save(receipt("r1","2026-10-01",1,"우유1L",3000,3000,ValidationStatus.PASS));rs.save(receipt("r2","2026-10-10",2,"우유1L",3200,3200,ValidationStatus.PASS_WITH_WARNINGS));rs.save(receipt("r3","2026-10-12",3,"우유1L",9999,9999,ValidationStatus.MISMATCH));IdentityResolution p=ps.confirm("r1",0,"우유1L",ProductType.STANDARD,"서울우유 1L",1);ps.resolveAndLinkExact("r2",0,"우유1L");ps.resolveAndLinkExact("r3",0,"우유1L");PriceHistory h=new PriceHistoryService(rs,ps).history(p.product.id);assertTrue(h.comparableTrend);assertEquals(2,h.observations.size());assertEquals(Long.valueOf(3200),h.latest);assertEquals(Long.valueOf(3000),h.min);assertEquals(Long.valueOf(3200),h.max);assertEquals(Long.valueOf(3100),h.average);}
 @Test public void nonStandardNeverClaimsAggregateTrend(){InMemoryReceiptStore rs=new InMemoryReceiptStore();InMemoryProductCatalogStore ps=new InMemoryProductCatalogStore();rs.save(receipt("r1","2026-10-01",1,"감자 1봉",5000,5000,ValidationStatus.PASS));IdentityResolution p=ps.confirm("r1",0,"감자 1봉",ProductType.NON_STANDARD,"감자 봉",1);PriceHistory h=new PriceHistoryService(rs,ps).history(p.product.id);assertFalse(h.comparableTrend);assertEquals(1,h.observations.size());assertEquals(Long.valueOf(5000),h.latest);assertNull(h.average);}
}
